export function catalogByStyle(style:string){return demoCatalog.filter(p=>p.styleTags.includes(style))}
export function catalogByCategory(category:string){return demoCatalog.filter(p=>p.category===category)}
export function catalogSearch(q:string){const t=q.toLowerCase().split(/\s+/).filter(Boolean);return demoCatalog.map(p=>({p,score:t.reduce((s,x)=>s+(p.title.toLowerCase().includes(x)?2:0)+(p.tags.includes(x)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.p)}
